import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"可怕的万圣节 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"可怕的万圣节 Linux 命令 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"可怕的万圣节 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"可怕的万圣节 Linux 命令 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171027 Scary Linux commands for Halloween","title":"可怕的万圣节 Linux 命令","tag":"201804","desc":""},"relativePath":"201804/20171027 Scary Linux commands for Halloween.md","filePath":"[post].md"}'),c={name:"201804/20171027 Scary Linux commands for Halloween.md"};function h(u,s,m,k,g,b){const e=p("Link");return o(),d("div",null,[s[18]||(s[18]=r(`<h1 id="可怕的万圣节-linux-命令" tabindex="-1">可怕的万圣节 Linux 命令 <a class="header-anchor" href="#可怕的万圣节-linux-命令" aria-label="Permalink to “可怕的万圣节 Linux 命令”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2017/10/animal-skeleton-100739983-large.jpg" alt=""></p><p>虽然现在不是万圣节，也可以关注一下 Linux 可怕的一面。什么命令可能会显示鬼、巫婆和僵尸的图像？哪个会鼓励“不给糖果就捣蛋”的精神？</p><h3 id="crypt" tabindex="-1">crypt <a class="header-anchor" href="#crypt" aria-label="Permalink to “crypt”">​</a></h3><p>好吧，我们一直看到 <code>crypt</code>。尽管名称不同，crypt 不是一个地窖，也不是垃圾文件的埋葬坑，而是一个加密文件内容的命令。现在，<code>crypt</code> 通常用一个脚本实现，通过调用一个名为 <code>mcrypt</code> 的二进制文件来模拟以前的 <code>crypt</code> 命令来完成它的工作。直接使用 <code>mycrypt</code> 命令是更好的选择。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcrypt x</span></span>
<span class="line"><span>Enter the passphrase (maximum of 512 characters)</span></span>
<span class="line"><span>Please use a combination of upper and lower case letters and numbers.</span></span>
<span class="line"><span>Enter passphrase:</span></span>
<span class="line"><span>Enter passphrase:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>File x was encrypted.</span></span></code></pre></div><p>请注意，<code>mcrypt</code> 命令会创建第二个扩展名为 <code>.nc</code> 的文件。它不会覆盖你正在加密的文件。</p><p><code>mcrypt</code> 命令有密钥大小和加密算法的选项。你也可以再选项中指定密钥，但 <code>mcrypt</code> 命令不鼓励这样做。</p><h3 id="kill" tabindex="-1">kill <a class="header-anchor" href="#kill" aria-label="Permalink to “kill”">​</a></h3><p>还有 <code>kill</code> 命令 - 当然并不是指谋杀，而是用来强制和非强制地结束进程，这取决于正确终止它们的要求。当然，Linux 并不止于此。相反，它有各种 <code>kill</code> 命令来终止进程。我们有 <code>kill</code>、<code>pkill</code>、<code>killall</code>、<code>killpg</code>、<code>rfkill</code>、<code>skill</code>（）读作 es-kill）、<code>tgkill</code>、<code>tkill</code> 和 <code>xkill</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ killall runme</span></span>
<span class="line"><span>[1] Terminated ./runme</span></span>
<span class="line"><span>[2] Terminated ./runme</span></span>
<span class="line"><span>[3]- Terminated ./runme</span></span>
<span class="line"><span>[4]+ Terminated ./runme</span></span></code></pre></div><h3 id="shred" tabindex="-1">shred <a class="header-anchor" href="#shred" aria-label="Permalink to “shred”">​</a></h3><p>Linux 系统也支持一个名为 <code>shred</code> 的命令。<code>shred</code> 命令会覆盖文件以隐藏其以前的内容，并确保使用硬盘恢复工具无法恢复它们。请记住，<code>rm</code> 命令基本上只是删除文件在目录文件中的引用，但不一定会从磁盘上删除内容或覆盖它。<code>shred</code> 命令覆盖文件的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shred dupes.txt</span></span>
<span class="line"><span>$ more dupes.txt</span></span>
<span class="line"><span>▒oΛ▒▒9▒lm▒▒▒▒▒o▒1־▒▒f▒f▒▒▒i▒▒h^}&amp;▒▒▒{▒▒</span></span></code></pre></div><h3 id="僵尸" tabindex="-1">僵尸 <a class="header-anchor" href="#僵尸" aria-label="Permalink to “僵尸”">​</a></h3><p>虽然不是命令，但僵尸在 Linux 系统上是很顽固的存在。僵尸基本上是没有完全清理掉的死亡进程的遗骸。进程_不应该_这样工作 —— 让死亡进程四处游荡，而不是简单地让它们死亡并进入数字天堂，所以僵尸的存在表明了让他们遗留于此的进程有一些缺陷。</p><p>一个简单的方法来检查你的系统是否有僵尸进程遗留，看看 <code>top</code> 命令的标题行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ top</span></span>
<span class="line"><span>top - 18:50:38 up 6 days, 6:36, 2 users, load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span>Tasks: 171 total, 1 running, 167 sleeping, 0 stopped, 3 zombie	\`&lt; ==\`</span></span>
<span class="line"><span>%Cpu(s): 0.0 us, 0.0 sy, 0.0 ni, 99.9 id, 0.1 wa, 0.0 hi, 0.0 si, 0.0 st</span></span>
<span class="line"><span>KiB Mem : 2003388 total, 250840 free, 545832 used, 1206716 buff/cache</span></span>
<span class="line"><span>KiB Swap: 9765884 total, 9765764 free, 120 used. 1156536 avail Mem</span></span></code></pre></div><p>可怕！上面显示有三个僵尸进程。</p><h3 id="at-midnight" tabindex="-1">at midnight <a class="header-anchor" href="#at-midnight" aria-label="Permalink to “at midnight”">​</a></h3><p>有时会在万圣节这么说，死者的灵魂从日落开始游荡直到午夜。Linux 可以通过 <code>at midnight</code> 命令跟踪它们的离开。用于安排在下次到达指定时间时运行的作业，<code>at</code> 的作用类似于一次性的 cron。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at midnight</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; echo &#39;the spirits of the dead have left&#39;</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 3 at Thu Oct 31 00:00:00 2017</span></span></code></pre></div><h3 id="守护进程" tabindex="-1">守护进程 <a class="header-anchor" href="#守护进程" aria-label="Permalink to “守护进程”">​</a></h3><p>Linux 系统也高度依赖守护进程 —— 在后台运行的进程，并提供系统的许多功能。许多守护进程的名称以 “d” 结尾。这个 “d” 代表<ruby>守护进程<rt>daemon</rt></ruby>，表明这个进程一直运行并支持一些重要功能。有的会用单词 “daemon” 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | grep sshd</span></span>
<span class="line"><span>root 1142 1 0 Oct19 ? 00:00:00 /usr/sbin/sshd -D</span></span>
<span class="line"><span>root 25342 1142 0 18:34 ? 00:00:00 sshd: shs [priv]</span></span>
<span class="line"><span>$ ps -ef | grep daemon | grep -v grep</span></span>
<span class="line"><span>message+ 790 1 0 Oct19 ? 00:00:01 /usr/bin/dbus-daemon --system --address=systemd: --nofork --nopidfile --systemd-activation</span></span>
<span class="line"><span>root 836 1 0 Oct19 ? 00:00:02 /usr/lib/accountsservice/accounts-daemon</span></span></code></pre></div><h3 id="万圣节快乐" tabindex="-1">万圣节快乐！ <a class="header-anchor" href="#万圣节快乐" aria-label="Permalink to “万圣节快乐！”">​</a></h3>`,26)),t("p",null,[s[2]||(s[2]=a("在 ",-1)),n(e,{href:"https://www.facebook.com/NetworkWorld/"},{default:i(()=>[...s[0]||(s[0]=[a("Facebook",-1)])]),_:1}),s[3]||(s[3]=a(" 和 ",-1)),n(e,{href:"https://www.linkedin.com/company/network-world"},{default:i(()=>[...s[1]||(s[1]=[a("LinkedIn",-1)])]),_:1}),s[4]||(s[4]=a(" 上加入 Network World 社区来对主题进行评论。",-1))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[6]||(s[6]=a("via: ",-1)),n(e,{href:"https://www.networkworld.com/article/3235219/linux/scary-linux-commands-for-halloween.html"},{default:i(()=>[...s[5]||(s[5]=[a("https://www.networkworld.com/article/3235219/linux/scary-linux-commands-for-halloween.html",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[7]||(s[7]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[8]||(s[8]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const w=l(c,[["render",h]]);export{y as __pageData,w as default};
